async function requestJson(url,timeout=14000,headers={Accept:"application/json"}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{signal:controller.signal,headers});if(!r.ok)throw Error("Service returned "+r.status);return await r.json()}finally{clearTimeout(timer)}}
function normalizePlace(p){const a=p.address||{};return{lat:Number(p.latitude??p.lat),lon:Number(p.longitude??p.lon),name:p.name||p.display_name||[p.city||a.city||a.town||a.village||a.postcode,p.admin1||a.state,p.country||a.country].filter(Boolean).join(", "),region:p.admin1||a.state||""}}
async function searchPlaces(q){q=q.trim();if(q.length<2)return[];const params=new URLSearchParams({name:q,count:8,language:"en",format:"json"});try{const j=await requestJson("https://geocoding-api.open-meteo.com/v1/search?"+params);const rows=(j.results||[]).map(p=>normalizePlace(p));if(rows.length)return rows}catch{}try{const j=await requestJson("https://photon.komoot.io/api/?"+new URLSearchParams({q,limit:8,lang:"en"}));return(j.features||[]).map(f=>{const p=f.properties||{},c=f.geometry?.coordinates||[];return{lat:c[1],lon:c[0],name:[p.name,p.city,p.state,p.country].filter((v,i,a)=>v&&a.indexOf(v)===i).join(", "),region:p.state||""}}).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon))}catch{return[]}}
async function geo(q){const rows=await searchPlaces(q);if(!rows.length)throw Error("Couldn't find that place. Try a city and state (for example, Boise, Idaho) or a ZIP code.");const norm=q.toLowerCase();return rows.find(p=>p.name.toLowerCase()===norm)||rows.find(p=>p.name.toLowerCase().startsWith(norm))||rows[0]}
async function reverse(lat,lon){try{const j=await requestJson("https://photon.komoot.io/reverse?"+new URLSearchParams({lat:String(lat),lon:String(lon),lang:"en"}),9000);const p=j.features?.[0];if(p)return normalizePlace({...p.properties,latitude:lat,longitude:lon})}catch{}return{lat,lon,name:"Current location",region:""}}

async function wx(p){let q={latitude:p.lat,longitude:p.lon,current:"temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,rain,showers,snowfall,weather_code,wind_speed_10m,wind_direction_10m,wind_gusts_10m,visibility",hourly:"temperature_2m,precipitation_probability,precipitation,snowfall,weather_code,wind_speed_10m,wind_gusts_10m,visibility",forecast_days:16,timezone:"auto",wind_speed_unit:"kmh"};let r=await fetch("https://api.open-meteo.com/v1/forecast?"+new URLSearchParams(q));if(!r.ok)throw Error("Weather service unavailable.");return r.json()}
async function getRoutes(a,b){const endpoints=["https://router.project-osrm.org/route/v1/driving/","https://routing.openstreetmap.de/routed-car/route/v1/driving/"];let last;for(const base of endpoints){try{const u=base+a.lon+","+a.lat+";"+b.lon+","+b.lat+"?alternatives=3&overview=full&geometries=geojson&steps=false";const j=await requestJson(u,18000);if(j.code==="Ok"&&j.routes?.length)return j.routes;last=j.message||j.code||"No route returned"}catch(e){last=e.message}}throw Error("Couldn't get a driving route from the routing services. Check your connection and try again. "+(last||""))}

function sample(coords,f){let p=coords[Math.max(0,Math.min(coords.length-1,Math.round(f*(coords.length-1))))];return{lon:p[0],lat:p[1]}}
function makePoints(coords,km){let n=Math.max(3,Math.min(60,Math.ceil(km/120.7)+1));return Array.from({length:n},(_,i)=>({...sample(coords,i/(n-1)),fraction:i/(n-1),distanceKm:km*i/(n-1)}))}
function forecast(p,duration){let hours=duration/3600*p.fraction,target=Date.now()+hours*36e5,h=p.weather.hourly,idx=0,delta=Infinity;h.time.forEach((t,i)=>{let d=Math.abs(new Date(t)-target);if(d<delta){delta=d;idx=i}});return{hours,idx,f:{temperature_2m:h.temperature_2m[idx],weather_code:h.weather_code[idx],wind_speed_10m:h.wind_speed_10m[idx],wind_gusts_10m:h.wind_gusts_10m[idx],visibility:h.visibility[idx],precipitation:h.precipitation[idx],precipitation_probability:h.precipitation_probability[idx],snowfall:h.snowfall[idx],time:h.time[idx]}}}
function assess(c){let w=mph(c.wind_speed_10m),g=mph(c.wind_gusts_10m),v=c.visibility/1609.34,k=c.weather_code;if(g>=45||w>=40||[56,57,66,67,75,86,95,96,99].includes(k)||v<.5)return{level:"HIGH RISK",cls:"danger",text:"Severe weather indicators. Check official advisories and consider delaying or changing plans."};if(g>=state.settings.wind||w>=state.settings.wind||v<2||[61,63,65,71,73,80,81,82,85].includes(k)||c.precipitation>1)return{level:"USE CAUTION",cls:"caution",text:"Weather may affect handling or visibility. Reduce speed and reassess conditions."};return{level:"LOWER RISK",cls:"",text:"No major weather risk indicators detected in this forecast. Conditions can change."}}
function current(data,place){let c=data.current;$("current-temp").innerHTML=temp(c.temperature_2m)+'<sup>°</sup>';$("current-condition").textContent=label(c.weather_code);$("weather-symbol").textContent=c.weather_code===0?"☀":c.weather_code>=71&&c.weather_code<=86?"❄":c.weather_code>=95?"ϟ":c.weather_code>=51?"☂":"◐";$("weather-location").textContent=place.toUpperCase();$("current-wind").textContent=mph(c.wind_speed_10m)+" mph";$("current-gust").textContent=mph(c.wind_gusts_10m)+" mph";$("current-visibility").textContent=(c.visibility/1609.34).toFixed(1)+" mi"}
function riskView(points,rt){let a=points.map(p=>assess(forecast(p,rt.duration).f)),rank={danger:3,caution:2,"":1};a.sort((x,y)=>rank[y.cls]-rank[x.cls]);let w=a[0];$("risk-indicator").textContent=w.level;$("risk-title").textContent=w.cls==="danger"?"Weather needs attention":w.cls==="caution"?"Use extra caution":"Generally favorable";$("risk-description").textContent=w.text;$("risk-icon").textContent=w.cls==="danger"?"!":w.cls==="caution"?"△":"◈";$("risk-card").dataset.risk=w.cls}
function checkpointView(points,rt){$("checkpoint-list").innerHTML=points.map((p,i)=>{let{hours,f}=forecast(p,rt.duration),r=assess(f),eta=new Date(Date.now()+hours*36e5).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"}),covered=Date.now()+hours*36e5<=Date.now()+15*864e5;return '<article class="checkpoint"><div class="checkpoint-distance">'+(i===0?"START":i===points.length-1?"DESTINATION":Math.round(p.distanceKm*.621371)+" MI")+'<small>'+eta+' ETA</small></div><div class="checkpoint-place"><strong>'+esc(p.name)+'</strong><small>'+esc(label(f.weather_code))+' · '+mph(f.wind_speed_10m)+' mph wind · '+Math.round(f.precipitation_probability||0)+'% precip.</small><span class="risk-tag '+(covered?r.cls:"caution")+'">'+(covered?r.level:"OUTSIDE FORECAST WINDOW")+'</span></div><div class="checkpoint-weather"><strong>'+(covered?temp(f.temperature_2m)+"°":"—")+'</strong><small>'+(covered?"GUST "+mph(f.wind_gusts_10m)+" MPH":"NO DATA")+'</small></div></article>'}).join("")}
async function elevation(points){try{let q=new URLSearchParams({latitude:points.map(p=>p.lat).join(","),longitude:points.map(p=>p.lon).join(",")}),r=await fetch("https://api.open-meteo.com/v1/elevation?"+q);if(!r.ok)throw Error();let j=await r.json();return Array.isArray(j.elevation)?j.elevation:[j.elevation]}catch{return points.map(()=>null)}}
function elevationView(points,vals){let high=points.map((p,i)=>({...p,e:vals[i]})).filter(p=>Number.isFinite(p.e)&&p.e>=1500);$("elevation-summary").innerHTML=high.length?high.map(p=>'<div class="elevation-item"><span><strong>'+esc(p.name)+'</strong><small>'+Math.round(p.distanceKm*.621371)+' mi from start</small></span><b>'+Math.round(p.e*3.28084).toLocaleString()+' ft</b></div>').join(""):'<div class="elevation-empty">No high-elevation sample detected. This is not a mountain-pass clearance check.</div>'}
async function alerts(points){let seen=new Set(),tasks=points.slice(0,7).map(async p=>{let key=p.lat.toFixed(1)+","+p.lon.toFixed(1);if(seen.has(key))return[];seen.add(key);try{let r=await fetch("https://api.weather.gov/alerts/active?point="+p.lat+","+p.lon,{headers:{Accept:"application/geo+json"}});if(!r.ok)return[];return((await r.json()).features||[]).map(f=>({...f.properties,pointName:p.name}))}catch{return[]}});let all=(await Promise.all(tasks)).flat(),unique=[...new Map(all.filter(a=>a.id).map(a=>[a.id,a])).values()];return unique.sort((a,b)=>({Extreme:4,Severe:3,Moderate:2,Minor:1}[b.severity]||0)-({Extreme:4,Severe:3,Moderate:2,Minor:1}[a.severity]||0))}
function alertsView(a){$("alerts-count").textContent=a.length?a.length+" ACTIVE":"0 ACTIVE";$("alerts-title").textContent=a.length?"Active alerts near route":"No active alerts returned";$("alerts-list").innerHTML=a.length?a.slice(0,12).map(x=>'<a class="alert-item '+(["Extreme","Severe"].includes(x.severity)?"alert-danger":"")+'" href="'+esc(x.web||"https://www.weather.gov/alerts")+'" target="_blank" rel="noopener"><span class="alert-severity">'+esc(x.severity||"ALERT")+'</span><span><strong>'+esc(x.event||"Weather alert")+'</strong><small>'+esc(x.headline||x.areaDesc||x.pointName)+'</small></span><b>↗</b></a>').join(""):'<p class="muted">No active NWS alerts returned for sampled points. This does not guarantee safe conditions.</p>'}
function stateFor(r){return Object.keys(roads).find(s=>r===s||r?.startsWith(s+" "))||null}
function roadView(points){let found=new Map();points.forEach(p=>{let s=stateFor(p.region);if(s)found.set(s,roads[s])});if(!found.size)found.set("Idaho",roads.Idaho);$("road-links").innerHTML=[...found].map(([s,v])=>'<a class="road-link" href="'+v[1]+'" target="_blank" rel="noopener"><span><strong>'+esc(v[0])+'</strong><small>'+esc(s)+'</small></span><b>↗</b></a>').join("")}
function routeOptionsView(){const el=$("route-options");if(!el)return;const choices=state.routeChoices||[];el.innerHTML=choices.length>1?choices.map((r,i)=>'<button type="button" class="route-choice '+(i===state.preferredRouteIndex?"active":"")+'" data-route-choice="'+i+'"><strong>'+(i===0?"ROUTE 1 · RECOMMENDED":"ROUTE "+(i+1))+'</strong><small>'+Math.round(r.distance/1609.34).toLocaleString()+' mi · '+Math.round(r.duration/60)+' min</small></button>').join(""):'<span class="route-choice-note">Showing the available route. Alternatives depend on routing data coverage.</span>';el.querySelectorAll("[data-route-choice]").forEach(b=>b.onclick=()=>{state.preferredRouteIndex=+b.dataset.routeChoice;$("route-form").requestSubmit()})}
function stateConditionsView(points,rt){const groups=new Map();points.forEach(p=>{const name=stateFor(p.region)||p.region||"State not identified";if(!groups.has(name))groups.set(name,[]);groups.get(name).push(p)});const entries=[...groups].filter(([name])=>name!=="State not identified");$("state-condition-list").innerHTML=entries.length?entries.map(([name,items],i)=>{const worst=items.map(p=>assess(forecast(p,rt.duration).f)).sort((a,b)=>({danger:3,caution:2,"":1}[b.cls]-({danger:3,caution:2,"":1}[a.cls])))[0];const mid=items[Math.floor(items.length/2)],f=forecast(mid,rt.duration).f;return '<button type="button" class="state-condition" data-state="'+esc(name)+'"><span class="state-index">'+String(i+1).padStart(2,"0")+'</span><span class="state-main"><strong>'+esc(name)+'</strong><small>'+items.length+' route checkpoints · '+esc(label(f.weather_code))+'</small></span><span class="state-weather"><strong>'+temp(f.temperature_2m)+'°</strong><small>'+mph(f.wind_speed_10m)+' mph wind</small></span><span class="risk-tag '+worst.cls+'">'+worst.level+'</span></button>'}).join(""):'<p class="muted">State names could not be identified for these route samples. Check the state DOT links below.</p>';$("state-condition-list").querySelectorAll("[data-state]").forEach(b=>b.onclick=()=>{const matches=points.filter(p=>(stateFor(p.region)||p.region)===b.dataset.state);if(matches.length&&state.map){const L=window.L;state.map.fitBounds(L.latLngBounds(matches.map(p=>[p.lat,p.lon])),{padding:[45,45],maxZoom:8});$("route-map").scrollIntoView({behavior:"smooth",block:"center"})}})}

const stateAbbreviations={"Alabama":"AL","Alaska":"AK","Arizona":"AZ","Arkansas":"AR","California":"CA","Colorado":"CO","Connecticut":"CT","Delaware":"DE","Florida":"FL","Georgia":"GA","Hawaii":"HI","Idaho":"ID","Illinois":"IL","Indiana":"IN","Iowa":"IA","Kansas":"KS","Kentucky":"KY","Louisiana":"LA","Maine":"ME","Maryland":"MD","Massachusetts":"MA","Michigan":"MI","Minnesota":"MN","Mississippi":"MS","Missouri":"MO","Montana":"MT","Nebraska":"NE","Nevada":"NV","New Hampshire":"NH","New Jersey":"NJ","New Mexico":"NM","New York":"NY","North Carolina":"NC","North Dakota":"ND","Ohio":"OH","Oklahoma":"OK","Oregon":"OR","Pennsylvania":"PA","Rhode Island":"RI","South Carolina":"SC","South Dakota":"SD","Tennessee":"TN","Texas":"TX","Utah":"UT","Vermont":"VT","Virginia":"VA","Washington":"WA","West Virginia":"WV","Wisconsin":"WI","Wyoming":"WY"};
function mapInit(){if(!window.L)return false;if(state.map)return true;state.map=window.L.map("route-map",{zoomControl:true,scrollWheelZoom:true,tap:true,preferCanvas:true}).setView([39.5,-98.35],3);state.stateBoundaryLayer=window.L.geoJSON(null,{style:()=>({color:"#526b69",weight:1.15,opacity:.9,fillColor:"#1d3030",fillOpacity:.78}),onEachFeature:(feature,layer)=>{const name=feature.properties?.name;if(!stateAbbreviations[name])return;layer.bindTooltip(name,{sticky:true,direction:"auto"});layer.on("click",()=>selectState(name))}}).addTo(state.map);state.roadNetworkLayer=window.L.layerGroup().addTo(state.map);setTimeout(()=>state.map?.invalidateSize(true),250);loadStateBoundaries();return true}
async function loadStateBoundaries(){try{const data=await requestJson("https://raw.githubusercontent.com/PublicaMundi/MappingAPI/master/data/geojson/us-states.json",18000);const features=(data.features||[]).filter(f=>stateAbbreviations[f.properties?.name]);if(features.length<48)throw Error("State boundary file was incomplete");state.stateFeatures=features;state.stateBoundaryLayer.addData({type:"FeatureCollection",features});const select=$("state-select");select.innerHTML='<option value="">Choose a state…</option>'+features.map(f=>'<option value="'+esc(f.properties.name)+'">'+esc(f.properties.name)+'</option>').sort((a,b)=>a.localeCompare(b)).join("");state.map.fitBounds(state.stateBoundaryLayer.getBounds(),{padding:[12,12]});$("map-road-count").textContent="50 STATES · SELECT ONE TO LOAD CONDITIONS";$("map-hint").textContent="TAP A STATE TO LOAD ROAD CONDITIONS";$("map-hint").classList.add("visible")}catch(error){console.error("State boundary load failed:",error);$("map-road-count").textContent="STATE MAP UNAVAILABLE · USE STATE SELECTOR";$("map-hint").textContent="CHOOSE A STATE ABOVE";$("map-hint").classList.add("visible");$("state-select").innerHTML='<option value="">Choose a state…</option>'+Object.keys(stateAbbreviations).sort().map(n=>'<option value="'+n+'">'+n+'</option>').join("")}}
function pointInRing(point,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1],cross=((yi>point[1])!==(yj>point[1]))&&(point[0]<(xj-xi)*(point[1]-yi)/(yj-yi||1e-12)+xi);if(cross)inside=!inside}return inside}
function pointInState(point,feature){const g=feature.geometry;if(g.type==="Polygon")return pointInRing(point,g.coordinates[0]);if(g.type==="MultiPolygon")return g.coordinates.some(poly=>pointInRing(point,poly[0]));return false}
function stateSamplePoints(feature){const bounds=state.stateBoundaryLayer.getLayers().find(l=>l.feature?.properties?.name===feature.properties.name)?.getBounds();if(!bounds)return[];const s=bounds.getSouth(),w=bounds.getWest(),n=bounds.getNorth(),e=bounds.getEast(),pts=[];for(let y=0;y<5;y++)for(let x=0;x<5;x++){const p=[w+(e-w)*(x+.5)/5,s+(n-s)*(y+.5)/5];if(pointInState(p,feature))pts.push({lat:+p[1].toFixed(3),lon:+p[0].toFixed(3)})}return pts.length?pts:[{lat:(s+n)/2,lon:(w+e)/2}]}
