async function stateIncidents(stateName,point){const config=native511[stateName];if(!config)return{supported:false,configured:false,events:[]};const key=state.incidentKeys[config.code]||(config.code==="ID"?state.incidentKey:"");if(!key)return{supported:true,configured:false,events:[],config};const url=config.base+"/api/v2/get/event?"+new URLSearchParams({key,format:"json"});const data=await requestJson(url,12000),rows=Array.isArray(data)?data:(data.Events||data.events||[]);return{supported:true,configured:true,config,events:rows.filter(e=>Number.isFinite(+e.Latitude)&&Number.isFinite(+e.Longitude)&&distanceMeters(point,{lat:+e.Latitude,lon:+e.Longitude})<8000)}}
async function inspectRoadSegment(latlng,roadInfo={}){const point={lat:latlng.lat,lon:latlng.lng};state.selectedRoad={...point,...roadInfo};const panel=$("road-inspector");panel.hidden=false;$("road-inspector-title").textContent="Checking selected road…";$("road-inspector-meta").textContent=point.lat.toFixed(4)+", "+point.lon.toFixed(4);$("road-inspector-results").innerHTML='<p class="muted">Looking up the road, forecast and official alerts…</p>';$("reroute-road").hidden=true;if(window.matchMedia("(max-width:720px)").matches)$("road-inspector").scrollIntoView({behavior:"smooth",block:"nearest"});try{const [place,weather]=await Promise.all([reverse(point.lat,point.lon),wx(point)]);state.selectedRoad={...point,...place,...roadInfo,weather};const f=weather.current,risk=assess({weather_code:f.weather_code,wind_speed_10m:f.wind_speed_10m,wind_gusts_10m:f.wind_gusts_10m,visibility:f.visibility,precipitation:f.precipitation});const [alertResult,incidentResult]=await Promise.allSettled([requestJson("https://api.weather.gov/alerts/active?point="+point.lat+","+point.lon,10000,{Accept:"application/geo+json"}),stateIncidents(stateFor(place.region),point)]);let alertsFound=alertResult.status==="fulfilled"?(alertResult.value.features||[]).map(x=>x.properties):[];let events=incidentResult.status==="fulfilled"?incidentResult.value.events:[];let incidentConfigured=incidentResult.status==="fulfilled"&&incidentResult.value.configured;const incidentConfig=incidentResult.status==="fulfilled"?incidentResult.value.config:null;const incidentSupported=incidentResult.status==="fulfilled"&&incidentResult.value.supported;const incidentMarkup=events.length?events.map(e=>'<div class="road-event '+(e.IsFullClosure?"road-event-danger":"")+'"><strong>'+esc(e.EventType||"Road event")+" · "+esc(e.RoadwayName||"Road")+'</strong><small>'+esc(e.Description||e.Comment||e.EventSubType||"Official 511 event")+'</small><small>'+esc(e.Severity||"Severity not provided")+(e.IsFullClosure?" · FULL CLOSURE":"")+'</small></div>').join(""):incidentConfigured?'<p class="muted">No '+esc(incidentConfig?.code||"511")+' traffic events found within 5 miles of this point.</p>':incidentSupported?'<p class="muted">Connect a '+esc(incidentConfig.code)+' 511 developer key to load this state’s official live road events. Use MANAGE 511 KEYS above.</p>':'<p class="muted">No direct state incident API is configured here yet. Open the official 511 / DOT source below.</p>';const alertMarkup=alertsFound.length?alertsFound.map(x=>'<div class="road-event '+(["Extreme","Severe"].includes(x.severity)?"road-event-danger":"")+'"><strong>'+esc(x.event||"Weather alert")+'</strong><small>'+esc(x.headline||x.areaDesc||"Active NWS alert")+'</small><small>NWS · '+esc(x.severity||"Severity not stated")+'</small></div>').join(""):'<p class="muted">No active National Weather Service alerts returned for this point.</p>';const official=roads[place.region]||roads[stateFor(place.region)]||null;$("road-inspector-title").textContent=roadInfo.name||place.name||"Selected road segment";$("road-inspector-meta").textContent=[roadInfo.type,roadInfo.ref,place.region||"State not identified",point.lat.toFixed(4)+", "+point.lon.toFixed(4)].filter(Boolean).join(" · ");$("road-inspector-results").innerHTML=(roadInfo.name?'<div class="road-event"><strong>ROAD DETAILS</strong><small>'+esc(roadInfo.name)+(roadInfo.type?" · "+esc(roadInfo.type):"")+(roadInfo.surface?" · "+esc(roadInfo.surface):"")+(roadInfo.maxspeed?" · Posted speed: "+esc(roadInfo.maxspeed):"")+'</small></div>':"")+'<div class="inspector-weather"><span class="risk-tag '+risk.cls+'">'+risk.level+'</span><strong>'+temp(f.temperature_2m)+'° · '+esc(label(f.weather_code))+'</strong><small>Wind '+mph(f.wind_speed_10m)+' mph · Gusts '+mph(f.wind_gusts_10m)+' mph · Visibility '+(f.visibility/1609.34).toFixed(1)+' mi</small></div><h4>WEATHER ALERTS</h4>'+alertMarkup+'<h4>ROAD EVENTS / ACCIDENTS</h4>'+incidentMarkup+(official?'<a class="inspector-official" href="'+official[1]+'" target="_blank" rel="noopener">OPEN '+esc(official[0].toUpperCase())+' LIVE MAP ↗</a>':'');const closure=events.some(e=>e.IsFullClosure||/closed|closure|blocked/i.test((e.Description||"")+" "+(e.EventType||"")));const danger=risk.cls==="danger"||alertsFound.some(x=>["Extreme","Severe"].includes(x.severity));if(state.route&& (closure||danger)){const alternatives=state.routeChoices.map((route,index)=>({route,index,clearance:nearestRouteDistance(point,route)})).filter(x=>x.clearance>2500).sort((x,y)=>y.clearance-x.clearance);if(alternatives.length){state.suggestedRoute=alternatives[0].index;$("reroute-road").hidden=false;$("reroute-road").textContent="USE ALTERNATE ROUTE "+(alternatives[0].index+1)+" ↗";$("reroute-road-note").textContent="Alternative route avoids this selected point by approximately "+(alternatives[0].clearance/1000).toFixed(1)+" km. Verify the full route and official restrictions."; }else{$("reroute-road-note").textContent="No available route alternative clearly avoids this point. Try a new destination waypoint or consult the official DOT.";}}else{$("reroute-road-note").textContent=state.route?"No high-risk weather alert or confirmed full closure was detected at this point. This is not a guarantee that the road is clear.":"Route planning is optional. Use the map to inspect any road; select ROUTE PLANNER only when you want a trip-specific alternative."}}catch(err){$("road-inspector-results").innerHTML='<p class="muted">Could not load all live details: '+esc(err.message)+'. Try again or use the official state 511 link.</p>';$("road-inspector-title").textContent="Selected road segment";}}
function manage511Keys(){const choices=Object.entries(native511).map(([name,v])=>v.code+" = "+name).join("\n");const code=(prompt("Which state key are you adding or clearing? Enter a code: ID, AK, AZ, GA, LA, NV or WI.\n\n"+choices)||"").trim().toUpperCase();const config=Object.values(native511).find(x=>x.code===code);if(!config){toast("That state is not in the current direct-API integration list.");return}const key=prompt("Paste the "+code+" 511 developer API key from "+config.keyUrl+". Leave blank to clear it. The key is stored in this browser only.");if(key===null)return;state.incidentKeys[code]=key.trim();if(code==="ID")state.incidentKey=key.trim();savePrefs();toast(key.trim()?code+" 511 key saved on this device.":code+" 511 key cleared.");if(state.selectedState){state.stateDataCache.delete(state.selectedState);selectState(state.selectedState)}if(state.selectedRoad&&state.route)inspectRoadSegment(state.selectedRoad)}
async function applySuggestedRoute(){if(!state.route||state.suggestedRoute==null)return;state.preferredRouteIndex=state.suggestedRoute;await check(new Event("submit",{cancelable:true,preventDefault(){}}));}

async function check(e){e.preventDefault();const origin=$("origin-input").value.trim(),destination=$("destination-input").value.trim();if(!origin||!destination)return;const button=$("route-form").querySelector('button[type="submit"]');button.disabled=true;button.querySelector("span").textContent="CHECKING…";msg("Finding both locations and calculating the driving route…");try{const [a,b]=await Promise.all([geo(origin),geo(destination)]);msg("Driving route found. Loading weather along the way…");state.routeChoices=await getRoutes(a,b);state.preferredRouteIndex=Math.min(state.preferredRouteIndex,state.routeChoices.length-1);const rt=state.routeChoices[state.preferredRouteIndex]||state.routeChoices[0];rt.duration=(rt.distance/1609.34/state.settings.speed)*3600;const pts=makePoints(rt.geometry.coordinates,rt.distance/1000);const points=[];for(let start=0;start<pts.length;start+=3){const batch=await Promise.all(pts.slice(start,start+3).map(async(p,j)=>{const i=start+j;const [place,weather]=await Promise.all([i===0?Promise.resolve(a):i===pts.length-1?Promise.resolve(b):reverse(p.lat,p.lon),wx(p)]);return{...p,...place,weather}}));points.push(...batch)}state.route={a,b,rt,points};routeOptionsView();stateConditionsView(points,rt);current(points[0].weather,a.name);riskView(points,rt);checkpointView(points,rt);$("route-title").textContent=a.name.split(",")[0]+" → "+b.name.split(",")[0];$("route-subtitle").textContent="Driving route estimate · "+points.length+" weather checkpoints";$("route-distance").textContent=Math.round(rt.distance/1609.34).toLocaleString()+" mi";const hrs=rt.distance/1609.34/state.settings.speed;$("route-duration").textContent=Math.floor(hrs)+"h "+Math.round(hrs%1*60)+"m*";$("checkpoint-count").textContent=points.length;$("route-weather-time").textContent="UPDATED "+new Date().toLocaleTimeString([],{hour:"numeric",minute:"2-digit"});$("route-results").hidden=false;$("empty-state").hidden=true;$("connection-label").textContent="FORECAST CONNECTED";roadView(points);stateConditionsView(points,rt);msg("Route and weather checkpoints loaded. Loading map and official alerts…");try{mapView(rt,points)}catch(err){console.warn("Map rendering fallback:",err);mapFallback(rt,points)}$("route-map").parentElement.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});const [alertResult,elevationResult]=await Promise.allSettled([alerts(points),elevation(points)]);if(alertResult.status==="fulfilled")alertsView(alertResult.value);else alertsView([]);if(elevationResult.status==="fulfilled")elevationView(points,elevationResult.value);else elevationView(points,[]);savePrefs();msg("Route ready. Check the alerts and official road resources before departure.")}catch(err){console.error(err);msg(err.message||"Could not check route.");toast(err.message||"Could not check route.")}finally{button.disabled=false;button.querySelector("span").textContent="CHECK ROUTE WEATHER"}}

function useCurrentLocation(){if(!navigator.geolocation){toast("Location unavailable in this browser.");return}msg("Getting current location…");navigator.geolocation.getCurrentPosition(async p=>{let q=await reverse(p.coords.latitude,p.coords.longitude);$("origin-input").value=q.name;try{current(await wx({lat:p.coords.latitude,lon:p.coords.longitude}),q.name);msg("Starting point set. Add your destination.")}catch(e){toast(e.message)}},e=>msg(e.code===1?"Location permission denied. Enter a city instead.":"Could not get location. Enter a city instead."),{enableHighAccuracy:true,timeout:12000,maximumAge:300000})}
function saveTrip(){if(!state.route)return;let a=saved().filter(x=>x.a.name!==state.route.a.name||x.b.name!==state.route.b.name);a.unshift({a:state.route.a,b:state.route.b,date:new Date().toISOString()});try{localStorage.setItem(STORE,JSON.stringify({settings:state.settings,truck:state.truck,incidentKey:state.incidentKey,savedRoutes:a.slice(0,8)}));savedView();toast("Trip saved on this device.")}catch{toast("Could not save trip.")}}
function openMaps(){if(!state.route)return;let{a,b}=state.route;window.open("https://www.google.com/maps/dir/?api=1&origin="+encodeURIComponent(a.name)+"&destination="+encodeURIComponent(b.name)+"&travelmode=driving","_blank","noopener")}
async function shareTrip(){if(!state.route)return;let{a,b}=state.route,t="Dustin's Trucking: "+a.name+" to "+b.name;if(navigator.share){try{await navigator.share({title:"Dustin's Trucking trip",text:t,url:window.location.href})}catch{}}else{try{await navigator.clipboard.writeText(t);toast("Trip details copied.")}catch{toast(t)}}}
async function wake(){try{if(state.wake){await state.wake.release();state.wake=null;$("wake-lock").textContent="◉ KEEP SCREEN ON";return}if(!navigator.wakeLock){toast("Screen wake lock is not supported.");return}state.wake=await navigator.wakeLock.request("screen");$("wake-lock").textContent="◉ SCREEN ON";state.wake.addEventListener("release",()=>{$("wake-lock").textContent="◉ KEEP SCREEN ON";state.wake=null})}catch{toast("Could not keep screen awake.")}}
function editTruck(){$("truck-length").value=state.truck.length;$("truck-height").value=state.truck.height;$("truck-weight").value=state.truck.weight;$("truck-dialog").showModal()}
function bindPlaceSearch(inputId,listId){const input=$(inputId),list=$(listId);let timer;input.addEventListener("input",()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<3){list.innerHTML="";return}timer=setTimeout(async()=>{const results=await searchPlaces(q);list.innerHTML=results.map(p=>'<option value="'+esc(p.name)+'"></option>').join("")},350)})}
function locateMap(){if(!navigator.geolocation){toast("Location is not available on this device.");return}toast("Finding your location…");navigator.geolocation.getCurrentPosition(pos=>{const p=[pos.coords.latitude,pos.coords.longitude];state.map?.setView(p,13);wx({lat:p[0],lon:p[1]}).then(w=>current(w,"CURRENT LOCATION")).catch(()=>{});},()=>toast("Location permission was unavailable. You can still pan and zoom anywhere."),{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
function init(){$("today-label").textContent=new Date().toLocaleDateString([],{weekday:"short",month:"short",day:"numeric"}).toUpperCase();$("footer-year").textContent=new Date().getFullYear();prefs();savedView();mapInit();if($("map-locate"))$("map-locate").onclick=locateMap;if($("state-select"))$("state-select").addEventListener("change",e=>selectState(e.target.value));if($("manage-state-keys"))$("manage-state-keys").onclick=manage511Keys;if($("state-back"))$("state-back").onclick=()=>{state.selectedState=null;state.roadNetworkLayer.clearLayers();$("state-overview").hidden=true;$("road-inspector").hidden=true;state.stateBoundaryLayer?.eachLayer(l=>l.setStyle({color:"#526b69",weight:1.15,fillColor:"#1d3030",fillOpacity:.78}));state.map?.fitBounds(state.stateBoundaryLayer.getBounds(),{padding:[12,12]});$("map-road-count").textContent="50 STATES · SELECT ONE TO LOAD CONDITIONS";};bindPlaceSearch("origin-input","origin-suggestions");bindPlaceSearch("destination-input","destination-suggestions");$("route-form").addEventListener("submit",check);$("reroute-road").onclick=applySuggestedRoute;$("set-idaho-key").onclick=manage511Keys;$("use-location").onclick=useCurrentLocation;$("settings-button").onclick=()=>$("settings-dialog").showModal();$("save-settings").onclick=()=>{state.settings.wind=+$("wind-threshold").value;state.settings.unit=$("temp-unit").value;state.settings.speed=+$("planning-speed").value;savePrefs();if(state.route){riskView(state.route.points,state.route.rt);checkpointView(state.route.points,state.route.rt)}toast("Preferences saved.")};$("clear-route").onclick=()=>{$("route-results").hidden=true;$("empty-state").hidden=false;state.route=null;msg("Enter your start and destination to see conditions along the way.")};$("open-maps").onclick=openMaps;$("save-route").onclick=saveTrip;$("refresh-route").onclick=()=>$("route-form").requestSubmit();$("wake-lock").onclick=wake;$("share-route").onclick=shareTrip;$("edit-truck").onclick=editTruck;$("edit-truck-settings").onclick=()=>{$("settings-dialog").close();editTruck()};$("save-truck").onclick=()=>{state.truck={length:$("truck-length").value,height:$("truck-height").value,weight:$("truck-weight").value};savePrefs();truckView();toast("Truck profile saved on this device.")};$("clear-saved").onclick=()=>{try{localStorage.setItem(STORE,JSON.stringify({settings:state.settings,truck:state.truck,savedRoutes:[]}));savedView()}catch{}};if("serviceWorker"in navigator&&location.protocol!=="file:")navigator.serviceWorker.register("./sw.js").catch(()=>{})}
document.addEventListener("DOMContentLoaded",init);